{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C47"],
      "claim": "Celiprolol, a tert-butylamino aryloxypropanolamine with a urea-type substituent, has absolute oral bioavailability of 30–70% in humans, supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Pafenolol, the closest urea-containing aryloxypropanolamine analogue, has systemic availability of 27 ± 5% after oral dosing in healthy subjects, clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Penbutolol, sharing the tert-butylamino hydroxypropoxy motif, has absolute oral bioavailability of 90% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Tertatolol, another tert-butylamino aryloxypropanolamine, has absolute oral bioavailability of 60% in healthy subjects, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Atenolol, a para-substituted aryloxypropanolamine beta-blocker, has absolute oral bioavailability of about 58% in healthy subjects, well above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved experimental evidence from structurally related beta-adrenergic antagonists reports oral bioavailability above the 20% threshold. The closest urea-containing analogues (celiprolol, pafenolol) and tert-butylamino analogues (penbutolol, tertatolol) consistently support high bioavailability, with no affirmative evidence of F < 20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement is available for the exact query molecule; prediction relies on transfer from moderately similar beta-blocker analogues.",
    "Some analogues show dose-dependent or variable bioavailability, but all reported values remain above the 20% threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

